package net.vibmc.network.packetevents.codec;
import com.github.retrooper.packetevents.event.PacketReceiveEvent;import com.github.retrooper.packetevents.protocol.player.User;import com.github.retrooper.packetevents.util.PacketEventsImplHelper;import io.netty.buffer.ByteBuf;import io.netty.channel.ChannelHandlerContext;import io.netty.handler.codec.MessageToMessageDecoder;import java.util.List;
public final class PacketEventsDecoder extends MessageToMessageDecoder<ByteBuf>{private User user;private Object player;public PacketEventsDecoder(User u,Object p){user=u;player=p;}public void setUser(User u){user=u;}public void setPlayer(Object p){player=p;}protected void decode(ChannelHandlerContext c,ByteBuf b,List<Object> out){try{Object event=PacketEventsImplHelper.handleServerBoundPacket(c.channel(),user,player,b,false);if(event instanceof PacketReceiveEvent&&!((PacketReceiveEvent)event).isCancelled())out.add(b.retain());}catch(Exception malformed){c.close();}}}
